func (st *ServerType) listenerAddrsForServerBlockKey(sblock serverBlock, key string,
	options map[string]interface{}) ([]string, error) {
	rawAddr, err := ParseAddress(key)
	if err != nil {
		return nil, fmt.Errorf("parsing key: %v", err)
	}

	trimmedHost := strings.TrimSpace(rawAddr.Host)
	addr := Address{
		Original: rawAddr.Original,
		Scheme:   rawAddr.Scheme,
		Host:     trimmedHost,
		Port:     rawAddr.Port,
		Path:     rawAddr.Path,
	}
	addr = addr.Normalize()

	httpPortNum := caddyhttp.DefaultHTTPPort
	httpsPortNum := caddyhttp.DefaultHTTPSPort
	defaultHTTPPortText := strconv.Itoa(httpPortNum)
	defaultHTTPSPortText := strconv.Itoa(httpsPortNum)
	httpPort := defaultHTTPPortText
	httpsPort := defaultHTTPSPortText
	if hport, ok := options["http_port"]; ok {
		configuredHTTPPort := hport.(int)
		httpPortNum = configuredHTTPPort
		httpPort = strconv.Itoa(httpPortNum)
	}
	if hsport, ok := options["https_port"]; ok {
		configuredHTTPSPort := hsport.(int)
		httpsPortNum = configuredHTTPSPort
		httpsPort = strconv.Itoa(httpsPortNum)
	}

	siteScheme := addr.Scheme
	sitePort := addr.Port
	lnPort := httpsPort
	if sitePort != "" {
		lnPort = sitePort
	} else if siteScheme == "http" {
